+        const attributes = element.attributes;
+        if (!attributes) continue;
+        for (let j = attributes.length - 1; j >= 0; j--) {
+            const attrName = attributes[j].name.toLowerCase();
+            const attrValue = (attributes[j].value || '').toLowerCase().trim();
