+// Heuristic check for potentially dangerous regex patterns that could cause
+// catastrophic backtracking (ReDoS) when used with untrusted input via $data.
+export function safeRegex(pattern: string): boolean {
+  // Limit pattern length to reduce attack surface
+  if (pattern.length > 100) return false
+  // Check for nested quantifiers: (X+)+, (X*)*, (X?)+
+ if (/\([^()]*[+*?][^()]*\)[+*?]/.test(pattern)) return false
+  // Check for quantified groups with overlapping alternation: (a|a)*, (a|ab)*
+  const groups = pattern.match(/\(([^()]*)\)([+*?])/g)
+  if (groups) {
+    for (const g of groups) {
+      const m = g.match(/\(([^()]*)\)([+*?])/)
+      if (m && m[1].includes("|")) {
+        const alts = m[1].split("|").filter((a) => a.length > 0)
+        for (let i = 0; i < alts.length; i++) {
+          for (let j = i + 1; j < alts.length; j++) {
+            if (alts[i] === alts[j]) return false
+            if (alts[i].startsWith(alts[j]) || alts[j].startsWith(alts[i])) return false
+          }
+        }
+      }
+    }
+  }
+  return true
+}
